];

const folderSection = ref<HTMLElement | null>(null);
const folderProgress = ref(0);
let folderFrame = 0;

const updateFolderProgress = () => {
  if (!folderSection.value) return;
  const rect = folderSection.value.getBoundingClientRect();
  const start = window.innerHeight * 0.82;
  const range = Math.max(window.innerHeight * 0.48, 1);
  folderProgress.value = Math.min(1, Math.max(0, (start - rect.top) / range));
};

const requestFolderProgress = () => {
  cancelAnimationFrame(folderFrame);
  folderFrame = requestAnimationFrame(updateFolderProgress);
};

onMounted(() => {
  updateFolderProgress();
  window.addEventListener("scroll", requestFolderProgress, { passive: true });
  window.addEventListener("resize", requestFolderProgress, { passive: true });
});

onBeforeUnmount(() => {
  cancelAnimationFrame(folderFrame);
  window.removeEventListener("scroll", requestFolderProgress);
  window.removeEventListener("resize", requestFolderProgress);
});
